 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = []
    for r in range(h - 2):
        for c in range(w - 2):
            if grid[r + 1][c + 1] == 2 and all(
                grid[r + dr][c + dc] == 3
                for dr in range(3) for dc in range(3)
                if (dr, dc) != (1, 1)
            ):
                markers.append((r + 1, c + 1))
    row_lines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= max(5, w - 2)]
    col_lines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= max(5, h - 2)]
    for mr, mc in markers:
        # A marker is associated with a line on which it lies, then replicated
        # on the next such line, as a 1-colored outline around the 2 line.
        if mr in row_lines:
            target = next((r for r in row_lines if r > mr), None)
            if target is not None:
                for dc in (-1, 1):
                    if 0 <= mc + dc < w:
                        out[target][mc + dc] = 1
                for dr in (-1, 1):
                    if 0 <= target + dr < h:
                        for dc in (-1, 0, 1):
                            if 0 <= mc + dc < w and out[target + dr][mc + dc] == 0:
                                out[target + dr][mc + dc] = 1
        elif mc in col_lines:
            target = next((c for c in col_lines if c > mc), None)
            if target is not None:
                for dr in (-1, 1):
                    if 0 <= mr + dr < h:
                        out[mr + dr][target] = 1
                for dc in (-1, 1):
                    if 0 <= target + dc < w:
                        for dr in (-1, 0, 1):
                            if 0 <= mr + dr < h and out[mr + dr][target + dc] == 0:
                                out[mr + dr][target + dc] = 1
    return out
