    h, w = len(grid), len(grid[0])
    markers = []
    for r in range(h - 2):
        for c in range(w - 2):
            if grid[r + 1][c + 1] == 2 and all(
                grid[r + dr][c + dc] == 3
                for dr in range(3) for dc in range(3)
                if (dr, dc) != (1, 1)
            ):
                markers.append((r + 1, c + 1))
    rows = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w - 2]
    cols = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 2]
    for r, c in markers:
        if c in cols:
            # Copy hollow 3x3 marker, recolored 1, to every column guide.
            for line in cols:
                if line == c: continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0: continue
                        rr, cc = r + dr, line + dc
                        if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                            out[rr][cc] = 1
        elif r in rows:
            for line in rows:
                if line == r: continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0: continue
                        rr, cc = line + dr, c + dc
                        if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                            out[rr][cc] = 1
    return out
