 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[r + dr][c + dc] == 3
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                   if (dr, dc) != (0, 0)):
                markers.append((r, c))

    # The 2s form long parallel guide lines. A marker emits a 1-colored
    # stroke perpendicular to its guide. Each other guide crossing along
    # that stroke gets a 3x3 halo, with the guide's center 2 preserved.
    guide_cols = [c for c in range(w)
                  if sum(grid[r][c] == 2 for r in range(h)) >= h - 2]
    guide_rows = [r for r in range(h)
                  if sum(v == 2 for v in grid[r]) >= w - 2]
    for r, c in markers:
        if c in guide_cols:
            for x in range(w):
                if out[r][x] == 0:
                    out[r][x] = 1
            for gc in guide_cols:
                if gc == c:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc = r + dr, gc + dc
                        if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                            out[rr][cc] = 1
        elif r in guide_rows:
            for y in range(h):
                if out[y][c] == 0:
                    out[y][c] = 1
            for gr in guide_rows:
                if gr == r:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc = gr + dr, c + dc
                        if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == 0:
                            out[rr][cc] = 1
    return out
